const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(text(value).toLowerCase());
};

const confirmation_token = text(input.confirmation_token);
const mobile = text(input.mobile);
const response = text(input.response).toLowerCase();
const response_note = text(input.response_note);
const confirm_response = toBoolean(input.confirm_response);

const errors = [];

if (!confirmation_token) {
  errors.push({
    field: 'confirmation_token',
    message: 'توکن تأیید الزامی است.',
  });
}

if (!mobile) {
  errors.push({
    field: 'mobile',
    message: 'شماره موبایل بیمار الزامی است.',
  });
}

if (mobile && !/^\+?[0-9]{8,15}$/.test(mobile)) {
  errors.push({
    field: 'mobile',
    message: 'شماره موبایل باید فقط شامل اعداد و در صورت نیاز علامت + باشد.',
  });
}

if (!['confirm', 'cancel', 'reschedule'].includes(response)) {
  errors.push({
    field: 'response',
    message: 'response باید confirm، cancel یا reschedule باشد.',
  });
}

if (response_note.length > 500) {
  errors.push({
    field: 'response_note',
    message: 'یادداشت پاسخ نباید بیشتر از 500 کاراکتر باشد.',
  });
}

if (confirm_response !== true) {
  errors.push({
    field: 'confirm_response',
    message: 'پاسخ بیمار باید به‌صورت صریح تأیید شود.',
  });
}

return [
  {
    json: {
      confirmation_token,
      mobile,
      response,
      response_note,
      confirm_response,
      validation_status: errors.length === 0 ? 'valid' : 'invalid',
      errors,
    },
  },
];

const db = $('Apply Appointment Confirmation Response').first().json;

const hasError =
  Boolean($json.error) ||
  Boolean($json.errorMessage) ||
  $json.success === false;

return [
  {
    json: {
      ...db,
      calendar_sync_status:
        hasError ? 'delete_failed' : 'deleted',
      calendar_sync_message:
        hasError
          ? 'نوبت لغو شد، اما حذف رویداد Google Calendar نیاز به بررسی دارد.'
          : 'رویداد Google Calendar حذف شد.',
    },
  },
];

return [
  {
    json: {
      success: false,
      result: $json.result ?? 'confirmation_response_failed',
      message: $json.message ?? 'پاسخ بیمار ثبت نشد.',
      confirmation_request_id:
        $json.confirmation_request_id ?? null,
      appointment_id:
        $json.appointment_id ?? null,
    },
  },
];

return [
  {
    json: {
      success: false,
      result: 'invalid_request',
      message: 'اطلاعات پاسخ تأیید ناقص یا نامعتبر است.',
      errors: $json.errors ?? [],
    },
  },
];

const db = $('Apply Appointment Confirmation Response').first().json;

return [{
  json: {
    ...db,
    calendar_sync_status: 'not_present',
    calendar_sync_message:
      'نوبت لغو شد و رویدادی در Google Calendar برای حذف وجود نداشت.',
  },
}];
